import java.util.Date; public class Person {private String firstName,middleName,lastName;private Date dateOfBirth;public Person(String f,String m,String l,Date d){firstName=f;middleName=m;lastName=l;dateOfBirth=d;}public String getFirstName(){return firstName;}public String getMiddleName(){return middleName;}public String getLastName(){return lastName;}public String getName(){return firstName+" "+middleName+" "+lastName;}public Date getDateOfBirth(){return dateOfBirth;}}
